"use strict";
// Lengths: text answers millimetres, a number of millimetres answers text.
var UNITS = { mm: 1, cm: 10, m: 1000 };

function millimetres(text) {
  var found = /^(\d*\.?\d+) *(mm|cm|m)$/.exec(text);
  if (!found) {
    return;
  }
  return parseFloat(found[1]) * UNITS[found[2]];
}

function written(amount) {
  return amount >= UNITS.m ? amount / UNITS.m + "m" : amount + "mm";
}

function read(value) {
  if (typeof value === "string") {
    return millimetres(value);
  }
  return written(value);
}

exports.read = read;
// One declared signature: the result follows the body.
exports.single = function (text) {
  return millimetres(text);
};
// The text overload admits a miss.
exports.pick = read;
exports.spans = function (value) {
  if (typeof value === "string") {
    var mm = millimetres(value);
    return mm === undefined ? undefined : [mm, mm * 2];
  }
  return written(value);
};
exports.measured = function (value) {
  if (typeof value === "string") {
    var mm = millimetres(value);
    return mm === undefined ? undefined : { mm: mm, text: value };
  }
  return written(value);
};
exports.ruler = {
  name: "ruler",
  read: function (value) {
    return read(value);
  },
};
